var Promise = require('any-promise')
var assert = require('assert')

module.exports = thenify

/**
 * Turn async functions into promises
 *
 * @param {Function} fn
 * @return {Function}
 * @api public
 */

function thenify(fn, options) {
  assert(typeof fn === 'function')
  return createWrapper(fn, options)
}

/**
 * Turn async functions into promises and backward compatible with callback
 *
 * @param {Function} fn
 * @return {Function}
 * @api public
 */

thenify.withCallback = function (fn, options) {
  assert(typeof fn === 'function')
  options = options || {}
  options.withCallback = true
  return createWrapper(fn, options)
}

function createCallback(resolve, reject, multiArgs) {
  // default to true
  if (multiArgs === undefined) multiArgs = true
  return function(err, value) {
    if (err) return reject(err)
    var length = arguments.length

    if (length <= 2 || !multiArgs) return resolve(value)

    if (Array.isArray(multiArgs)) {
      var values = {}
      for (var i = 1; i < length; i++) values[multiArgs[i - 1]] = arguments[i]
      return resolve(values)
    }

    var values = new Array(length - 1)
    for (var i = 1; i < length; ++i) values[i - 1] = arguments[i]
    resolve(values)
  }
}

function createWrapper(fn, options) {
  options = options || {}
  var name = fn.name;
  name = (name || '').replace(/\s|bound(?!$)/g, '')
  var newFn = function () {
    var self = this
    var len = arguments.length
    if (options.withCallback) {
      var lastType = typeof arguments[len - 1]
      if (lastType === 'function') return fn.apply(self, arguments)
    }
    var args = new Array(len + 1)
    for (var i = 0; i < len; ++i) args[i] = arguments[i]
    var lastIndex = i
    return new Promise(function (resolve, reject) {
      args[lastIndex] = createCallback(resolve, reject, options.multiArgs)
      fn.apply(self, args)
    })
  }
  Object.defineProperty(newFn, 'name', { value: name })
  return newFn
}

var assert = require('assert')

var thenify = require('..')

it('fn.name', function () {
  function someCrazyName() {}

  assert.equal('someCrazyName', thenify(someCrazyName).name)
  assert.equal('someCrazyName', thenify(someCrazyName).name)
  // In ES6 spec, functions can infer the name of an anonymous function from its syntactic position.
  var noname = function () {}
  var name = noname.name

  assert.equal(name, thenify(noname).name)
  assert.equal(name, thenify.withCallback(noname).name)
})

it('fn.name (bound function)', function () {
  function bound() {}
  assert.equal('bound', thenify(bound).name)
  assert.equal('bound', thenify.withCallback(bound).name)

  var noname = (function () {}).bind(this)
  assert.equal('', thenify(noname).name)
  assert.equal('', thenify.withCallback(noname).name)
})

it('fn(callback(err))', function () {
  function fn(cb) {
    setTimeout(function () {
      cb(new Error('boom'))
    }, 0)
  }

  return thenify(fn)().then(function () {
    throw new Error('bang')
  }).catch(function (err) {
    assert.equal(err.message, 'boom')
  })
})

it('fn(callback(null, value))', function () {
  function fn(cb) {
    cb(null, true)
  }

  return thenify(fn)().then(function (val) {
    assert.equal(val, true)
  })
})

it('fn(callback(null, values...))', function () {
  function fn(cb) {
    cb(null, 1, 2, 3)
  }

  return thenify(fn)().then(function (values) {
    assert.deepEqual(values, [1, 2, 3])
  })
})

it('fn(..args, callback())', function () {
  function fn(a, b, c, cb) {
    cb(null, a, b, c)
  }

  return thenify(fn)(1, 2, 3).then(function (values) {
    assert.deepEqual(values, [1, 2, 3])
  })
})

it('unicode function name', function () {
  function 你好$hello_123(a, b, c, cb) {
    cb(null, a, b, c)
  }
  var wrapper = thenify(你好$hello_123)
  assert.equal(wrapper.name, '你好$hello_123')
  wrapper(1, 2, 3).then(function (values) {
    assert.deepEqual(values, [1, 2, 3])
  })
})

it('invalid function name', function () {
  function fn(a, b, c, cb) {
    cb(null, a, b, c)
  }

  Object.defineProperty(fn, 'name', { value: 'fake(){a.b;})();(function(){//' })
  var wrapper = thenify(fn)
  assert.equal(wrapper.name, fn.name)
  wrapper(1, 2, 3).then(function (values) {
    assert.deepEqual(values, [1, 2, 3])
  })
})

var assert = require('assert')

var promisify = require('..')

var setImmediate = global.setImmediate || function (fn) {
  process.nextTick(fn)
}

describe('options', function () {
  describe('.withCallback', function () {
    function fn(cb) {
      cb(null, true)
    }

    it('promise', function () {
      return promisify(fn, { withCallback: true })().then(function (val) {
        assert.equal(val, true)
      })
    })

    it('callback', function (done) {
      return promisify(fn, { withCallback: true })(function (err, val) {
        assert.equal(val, true)
        done()
      })
    })
  })

  describe('.multiArgs', function () {
    function fn(cb) {
      cb(null, 1, 2, 3)
    }

    it('default to true', function () {
      return promisify(fn)().then(function (values) {
        assert.deepEqual(values, [1, 2, 3])
      })
    })

    it('set to false', function () {
      return promisify(fn, { multiArgs: false })().then(function (value) {
        assert.equal(value, 1)
      })
    })

    it('set to array', function () {
      return promisify(fn, { multiArgs: [ 'one', 'tow', 'three' ] })().then(function (value) {
        assert.deepEqual(value, {
          one: 1,
          tow: 2,
          three: 3
        })
      })
    })
  })
})

var assert = require('assert')

var promisify = require('../').withCallback

describe('with callback backward compatible', function () {
  describe('fn.name', function () {
    function someCrazyName() {}

    it('should set function name by default', function () {
      assert.equal('someCrazyName', promisify(someCrazyName).name)
    })

    it('should set name to empty', function () {
      assert.equal('', promisify(function() {}).name)
    })
  })

  describe('fn(callback(err)', function () {
    function fn(cb) {
      setTimeout(function () {
        cb(new Error('boom'))
      }, 0)
    }

    it('promise', function () {
      return promisify(fn)().then(function () {
        throw new Error('bang')
      }).catch(function (err) {
        assert.equal(err.message, 'boom')
      })
    })

    it('callback', function (done) {
      promisify(fn)(function (err) {
        assert.equal(err.message, 'boom')
        done()
      })
    })
  })

  describe('fn(callback(null, value))', function () {
    function fn(cb) {
      cb(null, true)
    }

    it('promise', function () {
      return promisify(fn)().then(function (val) {
        assert.equal(val, true)
      })
    })

    it('callback', function (done) {
      return promisify(fn)(function (err, val) {
        assert.equal(val, true)
        done()
      })
    })
  })

  describe('fn(callback(null, values...))', function () {
    function fn(cb) {
      cb(null, 1, 2, 3)
    }

    it('promise', function () {
      return promisify(fn)().then(function (values) {
        assert.deepEqual(values, [1, 2, 3])
      })
    })

    it('callback', function (done) {
      promisify(fn)(function (err, val1, val2, val3) {
        assert.equal(val1, 1)
        assert.equal(val2, 2)
        assert.equal(val3, 3)
        done()
      })
    })
  })

  describe('fn(..args, callback())', function () {
    function fn(a, b, c, cb) {
      cb(null, a, b, c)
    }

    it('promise', function () {
      return promisify(fn)(1, 2, 3).then(function (values) {
        assert.deepEqual(values, [1, 2, 3])
      })
    })

    it('callback', function (done) {
      promisify(fn)(1, 2, 3, function (err, val1, val2, val3) {
        assert.equal(val1, 1)
        assert.equal(val2, 2)
        assert.equal(val3, 3)
        done()
      })
    })
  })
})

var assert = require('assert')

var promisify = require('..')

var setImmediate = global.setImmediate || function (fn) {
  process.nextTick(fn)
}

describe('Promisify', function () {
  it('should reject errors', function (done) {
    function fn(done) {
      setImmediate(function () {
        var err = new Error('boom')
        err.boom = 'boom'
        done(err)
      })
    }

    var prom = promisify(fn)

    prom().catch(function (err) {
      assert.equal(err.message, 'boom')
      assert.equal(err.boom, 'boom')
      done()
    })
  })

  it('should reject errors with arguments', function (done) {
    function fn(a, b, done) {
      setImmediate(function () {
        done(new Error('boom'))
      })
    }

    var prom = promisify(fn)

    prom(1, 2).catch(function (err) {
      assert.equal(err.message, 'boom')
      done()
    })
  })

  /**
  * bluebird can resolve multiple arguments,
  * but v8 promises can't. -_-
  */
  it('should return the result', function (done) {
    function fn(done) {
      setImmediate(function () {
        done(null, 1)
      })
    }

    var prom = promisify(fn)

    prom().then(function (a) {
      assert.equal(a, 1)
      done()
    })
  })
})

